//! Desktop entry point and stable headless command line interface.
use native_browser::{headless, browser::Browser, model::Size};
fn main(){let args:Vec<String>=std::env::args().collect(); if args.get(1).map(String::as_str)==Some("--headless"){let url=args.get(2).map(String::as_str).unwrap_or("about:blank"); let out=args.iter().position(|x|x=="--output").and_then(|i|args.get(i+1)).map(String::as_str).unwrap_or("output.png"); let w=args.iter().position(|x|x=="--width").and_then(|i|args.get(i+1)).and_then(|x|x.parse().ok()).unwrap_or(800); let h=args.iter().position(|x|x=="--height").and_then(|i|args.get(i+1)).and_then(|x|x.parse().ok()).unwrap_or(600); if let Err(e)=headless::render_png(url,w,h,out){eprintln!("{e}");std::process::exit(1)}} else {let url=args.get(1).map(String::as_str).unwrap_or("about:blank"); let _browser=Browser::open(url,Size{width:800.0,height:600.0}); println!("native-browser: {url}");}}
